from __future__ import annotations

import copy
from pathlib import Path
from typing import Optional, Sequence

from QuantizedPianoRoll import (
    InstrEvt,
    KeyEvt,
    MeterEvt,
    Mode,
    NoteEvt,
    Qpr,
    SPQNEvt,
)
from DataRepresentation import BDB, DTPR, MTPR, PTPR, TPQN

try:
    from dtpr_to_qpr import (
        DEFAULT_COMMENTS,
        infer_last_stime,
        infer_meter_events,
        infer_spqn_events,
        sorted_beats,
        sorted_mtpr_notes,
    )
except ImportError:
    DEFAULT_COMMENTS = [
        "Generated by DualTimePianoRoll.py",
        "Assumption: each BDB beat corresponds to a quarter note.",
    ]

    def sorted_beats(bdb: BDB):
        return sorted(bdb.beats.values(), key=lambda beat: (beat.beat_time, beat.id))

    def sorted_mtpr_notes(mtpr: MTPR):
        return sorted(
            mtpr.notes.values(),
            key=lambda note: (note.abs_ontick, note.abs_offtick, note.id),
        )

    def infer_last_stime(beats, notes) -> int:
        last_note_tick = max((note.abs_offtick for note in notes), default=0)
        last_beat_tick = max(0, (len(beats) - 1) * TPQN)
        return max(last_note_tick, last_beat_tick)

    def _align_last_stime_to_barline(last_stime: int, meter_start: int, barlen: int) -> int:
        if barlen <= 0:
            return last_stime
        relative = last_stime - meter_start
        if relative <= 0:
            return meter_start
        remainder = relative % barlen
        return last_stime if remainder == 0 else last_stime + (barlen - remainder)

    def infer_meter_events(beats, last_stime: int, *, align_end_to_barline: bool = True):
        if not beats:
            aligned = (
                _align_last_stime_to_barline(last_stime, 0, 4 * TPQN)
                if align_end_to_barline
                else last_stime
            )
            return [(0, 4, 4, 4 * TPQN), (aligned, 0, 0, 0)]

        downbeat_indices = [idx for idx, beat in enumerate(beats) if beat.is_downbeat]
        if not downbeat_indices:
            downbeat_indices = [0]

        spans = [
            right - left
            for left, right in zip(downbeat_indices, downbeat_indices[1:])
            if right > left
        ]
        current_numer = max(1, spans[0] if spans else 4)
        meter_events = []

        first_downbeat = downbeat_indices[0]
        if first_downbeat > 0:
            meter_events.append((0, current_numer, 4, first_downbeat * TPQN))
            meter_events.append((first_downbeat * TPQN, current_numer, 4, current_numer * TPQN))
        else:
            meter_events.append((0, current_numer, 4, current_numer * TPQN))

        for idx in range(1, len(downbeat_indices)):
            bar_start = downbeat_indices[idx]
            numer = (
                downbeat_indices[idx + 1] - downbeat_indices[idx]
                if idx < len(downbeat_indices) - 1
                else current_numer
            )
            numer = max(1, numer)
            if numer != current_numer:
                meter_events.append((bar_start * TPQN, numer, 4, numer * TPQN))
                current_numer = numer

        last_meter_start, _, _, last_barlen = meter_events[-1]
        aligned = (
            _align_last_stime_to_barline(last_stime, last_meter_start, last_barlen)
            if align_end_to_barline
            else last_stime
        )
        meter_events.append((aligned, 0, 0, 0))
        return meter_events

    def infer_spqn_events(beats):
        if len(beats) < 2:
            return [(0, 0.5, 120.0)]

        events = []
        prev_spqn = None
        for beat_idx, (left, right) in enumerate(zip(beats, beats[1:])):
            spqn = right.beat_time - left.beat_time
            if spqn <= 0:
                continue
            if prev_spqn is None or abs(prev_spqn - spqn) > 1e-6:
                events.append((beat_idx * TPQN, spqn, 60.0 / spqn))
                prev_spqn = spqn
        return events or [(0, 0.5, 120.0)]


REAL_TIME_SENTINEL = -1.0
DEFAULT_REAL_TIME_THRESHOLD_SEC = 0.0


class DualTimePianoRoll(Qpr):
    """QPR-compatible piano roll with DTPR real-time note columns."""

    def __init__(self, fname: Optional[str | Path] = None):
        super().__init__(None)
        self._raw_real_onoffs = {}
        if fname is not None:
            self.read_file(str(fname))
            self._normalize_real_times()

    @classmethod
    def read_dtpr_file(cls, path: str | Path) -> "DualTimePianoRoll":
        qpr = cls()
        qpr.read_file(str(path))
        qpr._normalize_real_times()
        return qpr

    def write_dtpr_file(
        self,
        path: str | Path,
        *,
        threshold_sec: float = DEFAULT_REAL_TIME_THRESHOLD_SEC,
        mode: Optional[Mode] = None,
    ) -> Path:
        output = Path(path)
        output.write_text(
            self.to_dtpr_str(threshold_sec=threshold_sec, mode=mode),
            encoding="utf-8",
        )
        return output

    @classmethod
    def from_dtpr_class(
        cls,
        dtpr: DTPR,
        *,
        name: Optional[str] = None,
        memo: Optional[str] = None,
        comments: Optional[Sequence[str]] = None,
        channel: int = 0,
        subvoice: int = 0,
        program: int = 0,
        instrument_name: str = "Default",
    ) -> "DualTimePianoRoll":
        qpr = cls()
        qpr.name = name
        qpr.memo = memo
        qpr.TPQN = TPQN
        qpr.comments = list(DEFAULT_COMMENTS if comments is None else comments)
        qpr.instrs = [InstrEvt(channel, program, instrument_name)]
        qpr.keys = [KeyEvt(0, "C", "major", 0)]

        beats = sorted_beats(dtpr.BDB)
        notes = sorted_mtpr_notes(dtpr.MTPR)
        last_stime = infer_last_stime(beats, notes)

        qpr.meters = [
            MeterEvt(*event)
            for event in infer_meter_events(beats, last_stime, align_end_to_barline=False)
        ]
        qpr.SPQNs = [SPQNEvt(*event) for event in infer_spqn_events(beats)]
        qpr.clefs = []
        qpr.chords = []
        qpr.notes = []
        qpr._raw_real_onoffs = {}

        for note_idx, mtpr_note in enumerate(notes):
            ptpr_note = dtpr.PTPR.notes.get(mtpr_note.id)
            real_ontime = None if ptpr_note is None else ptpr_note.real_ontime
            real_offtime = None if ptpr_note is None else ptpr_note.real_offtime
            note = NoteEvt(
                str(note_idx),
                mtpr_note.abs_ontick,
                mtpr_note.abs_offtick,
                mtpr_note.pitch,
                channel,
                subvoice,
                str(mtpr_note.id),
                onsec=real_ontime,
                offsec=real_offtime,
            )
            qpr.notes.append(note)
            qpr._raw_real_onoffs[note.ID] = (real_ontime, real_offtime)

        return qpr

    def to_dtpr_class(self) -> DTPR:
        self._assert_dtpr_tpqn()
        bdb = self.to_beats()
        mtpr = MTPR()
        ptpr = PTPR()

        for note in self.notes:
            note_id = self._note_id(note)
            on_beat_id, on_metrical_pos = self._abs_tick_to_rel_tick(note.onstime, bdb)
            off_beat_id, off_metrical_pos = self._abs_tick_to_rel_tick(note.offstime, bdb)
            ideal_ontime = self._tick_to_sec(note.onstime)
            ideal_offtime = self._tick_to_sec(note.offstime)
            real_ontime = ideal_ontime if note.onsec is None else note.onsec
            real_offtime = ideal_offtime if note.offsec is None else note.offsec

            mtpr.add_mtpr_note(
                note_id,
                note.pitch,
                note.onstime,
                on_beat_id,
                on_metrical_pos,
                note.offstime,
                off_beat_id,
                off_metrical_pos,
            )
            ptpr.add_ptpr_note(
                note_id,
                note.pitch,
                ideal_ontime,
                real_ontime,
                ideal_offtime,
                real_offtime,
            )

        return DTPR(bdb, mtpr, ptpr)

    @classmethod
    def dtpr_file_to_dtpr_class(cls, path: str | Path) -> DTPR:
        return cls.read_dtpr_file(path).to_dtpr_class()

    @classmethod
    def dtpr_class_to_dtpr_file(
        cls,
        dtpr: DTPR,
        path: str | Path,
        *,
        threshold_sec: float = DEFAULT_REAL_TIME_THRESHOLD_SEC,
        **kwargs,
    ) -> Path:
        return cls.from_dtpr_class(dtpr, **kwargs).write_dtpr_file(
            path,
            threshold_sec=threshold_sec,
        )

    @classmethod
    def qpr_to_dtpr_class(cls, qpr_or_path: Qpr | str | Path) -> DTPR:
        if isinstance(qpr_or_path, (str, Path)):
            qpr = cls.read_dtpr_file(qpr_or_path)
        else:
            qpr = cls.from_qpr(qpr_or_path)
            qpr._set_missing_real_times_to_ideal()
        return qpr.to_dtpr_class()

    @classmethod
    def dtpr_to_qpr(cls, dtpr: DTPR, **kwargs) -> Qpr:
        qpr = cls.from_dtpr_class(dtpr, **kwargs)
        result = Qpr()
        result.__dict__.update(copy.deepcopy(qpr.__dict__))
        for note in result.notes:
            note.onsec = None
            note.offsec = None
        return result

    @classmethod
    def dtpr_to_ipr(cls, dtpr: DTPR) -> PTPR:
        return dtpr.PTPR

    @classmethod
    def dtpr_to_beats(cls, dtpr: DTPR) -> BDB:
        return dtpr.BDB

    @classmethod
    def ipr_beats_to_dtpr(cls, ipr: PTPR, beats: BDB, *, quantize: bool = False) -> DTPR:
        dtpr = DTPR(beats, MTPR(), ipr)
        if quantize:
            dtpr.quantize_init_real_time()
        return dtpr

    @classmethod
    def from_qpr(cls, qpr: Qpr) -> "DualTimePianoRoll":
        result = cls()
        result.__dict__.update(copy.deepcopy(qpr.__dict__))
        result._raw_real_onoffs = {}
        return result

    def to_dtpr_str(
        self,
        *,
        threshold_sec: float = DEFAULT_REAL_TIME_THRESHOLD_SEC,
        mode: Optional[Mode] = None,
    ) -> str:
        if mode is None:
            mode = Mode.SITCH

        lines = [f"// {comment}" for comment in self.comments]
        lines += [f"# Name\t{self.name}"] if self.name is not None else []
        lines += [f"# Memo\t{self.memo}"] if self.memo is not None else []
        lines += [f"# nBar\t{self.n_bar}"] if self.n_bar is not None else []
        lines += [f"# TPQN\t{self.TPQN}"]
        lines += [str(event) for event in self.instrs]
        lines += [str(event) for event in self.keys]
        lines += [str(event) for event in self.meters]
        lines += [str(event) for event in self.SPQNs]
        lines += [str(event) for event in self.clefs]

        for note in self.notes:
            ideal_ontime = self._tick_to_sec(note.onstime)
            ideal_offtime = self._tick_to_sec(note.offstime)
            real_ontime = ideal_ontime if note.onsec is None else note.onsec
            real_offtime = ideal_offtime if note.offsec is None else note.offsec
            lines.append(
                note.to_str(mode=mode, qprx=False)
                + "\t"
                + self._format_real_time(real_ontime, ideal_ontime, threshold_sec)
                + "\t"
                + self._format_real_time(real_offtime, ideal_offtime, threshold_sec)
            )

        return "\n".join(lines) + "\n"

    def to_beats(self) -> BDB:
        self._assert_dtpr_tpqn()
        bdb = BDB()
        last_stime = self._last_tick_for_beats()
        barstarts = set(self._barstart_ticks(last_stime))

        for tick in range(0, last_stime + 1, self.TPQN):
            bdb.add_beat(self._tick_to_sec(tick), tick in barstarts)

        if not bdb.beats:
            bdb.add_beat(0.0, True)

        return bdb

    def _normalize_real_times(self):
        self._assert_dtpr_tpqn()
        self._raw_real_onoffs = {}
        for note in self.notes:
            raw_onsec = note.onsec
            raw_offsec = note.offsec
            self._raw_real_onoffs[note.ID] = (raw_onsec, raw_offsec)
            ideal_ontime = self._tick_to_sec(note.onstime)
            ideal_offtime = self._tick_to_sec(note.offstime)
            if raw_onsec == REAL_TIME_SENTINEL:
                note.onsec = ideal_ontime
            if raw_offsec == REAL_TIME_SENTINEL:
                note.offsec = ideal_offtime

    def _set_missing_real_times_to_ideal(self):
        for note in self.notes:
            if note.onsec is None:
                note.onsec = self._tick_to_sec(note.onstime)
            if note.offsec is None:
                note.offsec = self._tick_to_sec(note.offstime)

    @staticmethod
    def _format_real_time(real_time: float, ideal_time: float, threshold_sec: float) -> str:
        if abs(real_time - ideal_time) < threshold_sec:
            return "-1"
        return f"{real_time:.6f}"

    def _tick_to_sec(self, tick: int) -> float:
        spqns = sorted(self.SPQNs, key=lambda event: event.stime)
        if not spqns:
            spqns = [SPQNEvt(0, 0.5, 120.0)]

        sec = 0.0
        current_tick = 0
        current_spqn = spqns[0].value

        for event in spqns:
            if event.stime <= current_tick:
                current_spqn = event.value
                continue
            if tick <= event.stime:
                return sec + (tick - current_tick) * current_spqn / self.TPQN
            sec += (event.stime - current_tick) * current_spqn / self.TPQN
            current_tick = event.stime
            current_spqn = event.value

        return sec + (tick - current_tick) * current_spqn / self.TPQN

    def _last_tick_for_beats(self) -> int:
        note_last = max((note.offstime for note in self.notes), default=0)
        meter_last = max((meter.stime for meter in self.meters), default=0)
        last_tick = max(note_last, meter_last)
        if last_tick % self.TPQN != 0:
            last_tick += self.TPQN - (last_tick % self.TPQN)
        return last_tick

    def _barstart_ticks(self, last_stime: int):
        meters = sorted(
            [meter for meter in self.meters if meter.barlen > 0],
            key=lambda meter: meter.stime,
        )
        if not meters:
            return [0]

        barstarts = []
        for idx, meter in enumerate(meters):
            next_stime = meters[idx + 1].stime if idx + 1 < len(meters) else last_stime
            if meter.barlen <= 0:
                continue
            tick = meter.stime
            while tick <= next_stime and tick <= last_stime:
                barstarts.append(tick)
                tick += meter.barlen
        return barstarts or [0]

    def _abs_tick_to_rel_tick(self, abs_tick: int, bdb: BDB):
        beat_idx = abs_tick // self.TPQN
        metrical_pos = abs_tick % self.TPQN
        if beat_idx >= len(bdb.index):
            beat_idx = len(bdb.index) - 1
            metrical_pos = self.TPQN
        beat = bdb.get_beat_from_idx(beat_idx)
        return beat.id, metrical_pos

    @staticmethod
    def _note_id(note: NoteEvt) -> int:
        try:
            return int(note.label)
        except (TypeError, ValueError):
            return int(note.ID)

    def _assert_dtpr_tpqn(self):
        if self.TPQN != TPQN:
            raise ValueError(
                f"DTPR conversion expects TPQN={TPQN}, but this piano roll has TPQN={self.TPQN}"
            )


def dtpr_file_to_dtpr_class(path: str | Path) -> DTPR:
    return DualTimePianoRoll.dtpr_file_to_dtpr_class(path)


def dtpr_class_to_dtpr_file(
    dtpr: DTPR,
    path: str | Path,
    *,
    threshold_sec: float = DEFAULT_REAL_TIME_THRESHOLD_SEC,
    **kwargs,
) -> Path:
    return DualTimePianoRoll.dtpr_class_to_dtpr_file(
        dtpr,
        path,
        threshold_sec=threshold_sec,
        **kwargs,
    )


def qpr_to_dtpr_class(qpr_or_path: Qpr | str | Path) -> DTPR:
    return DualTimePianoRoll.qpr_to_dtpr_class(qpr_or_path)


def dtpr_to_qpr(dtpr: DTPR, **kwargs) -> Qpr:
    return DualTimePianoRoll.dtpr_to_qpr(dtpr, **kwargs)


def dtpr_to_ipr(dtpr: DTPR) -> PTPR:
    return DualTimePianoRoll.dtpr_to_ipr(dtpr)


def dtpr_to_beats(dtpr: DTPR) -> BDB:
    return DualTimePianoRoll.dtpr_to_beats(dtpr)


def ipr_beats_to_dtpr(ipr: PTPR, beats: BDB, *, quantize: bool = False) -> DTPR:
    return DualTimePianoRoll.ipr_beats_to_dtpr(ipr, beats, quantize=quantize)
